import { IngestPipeline, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Data model for product interaction events
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: string; // view, cart, purchase
  properties: Record<string, any>; // flexible JSON for properties like price, page, etc.
}

// Ingest pipeline for product events - creates table, stream, and HTTP ingest endpoint
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["user_id", "event_ts", "product_id"] // optimize for user-based queries
  },
  stream: true,     // Redpanda topic for buffering
  ingestApi: true   // POST /ingest/ProductEvent endpoint
});

