// API Endpoints for egress

// Top Products API
interface TopProductsParams {
  limit?: number;
}

export const topProductsApi = new Api<TopProductsParams, TopProductsRow>(
  "top-products",
  async ({ limit = 10 }, { client }) => {
    const result = await client.query.execute(sql.statement`
      SELECT product_id, view_count, cart_count, purchase_count, total_revenue
      FROM TopProducts
      ORDER BY total_revenue DESC, purchase_count DESC
      LIMIT ${limit}
    `);
    return await result.json();
  }
);

